  [5281] = {{"Find Egan. You only know that he was last seen around Stratholme."},{{1,'Caretaker Alen'}},{{1,'Egan'}},nil,nil,{1423,69.93,53.72},{1423,11.36,26.60},nil,nil,nil},
  [5282] = {{"Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!","Free 15 Restless Souls and return to Egan."},{{1,'Egan'}},{{1,'Egan'}},{{13315,'Testament of Hope'}},nil,{1423,11.36,26.60},{1423,11.36,26.60},{{5281,"The Restless Souls"}},nil,{13289,'Egan\'s Blaster'}},
