  [5342] = {{"Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.","Be warned, Weldon will probably be well protected by Alliance scum."},{{1,'Alexi Barov'}},{{1,'Alexi Barov'}},{{14022,'Barov Peasant Caller'}},nil,{1420,83.06,71.60},{1420,83.06,71.60},{{5341,"Barov Family Fortune"}},nil,nil},
  [5343] = {{"Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."},{{1,'Weldon Barov'}},{{1,'Weldon Barov'}},nil,nil,{1422,43.45,83.73},{1422,43.45,83.73},nil,nil,nil},
  [5344] = {{"Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.","Be warned, Alexi will probably be well protected by Horde filth."},{{1,'Weldon Barov'}},{{1,'Weldon Barov'}},{{14023,'Barov Peasant Caller'}},nil,{1422,43.45,83.73},{1422,43.45,83.73},{{5343,"Barov Family Fortune"}},nil,nil},
  [5381] = {{"Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village."},{{1,'Taiga Wisemane'}},{{1,'Taiga Wisemane'}},nil,{{81,250}},{1443,25.82,68.21},{1443,25.82,68.21},nil,nil,{14523,'Demon Pick'}},
