  [5384] = {{"Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.","Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff."},{{1,'Eva Sarkhoff'}},{{1,'Eva Sarkhoff'}},{{13544,'Spectral Essence'},{15805,'Penelope\'s Rose'},{15806,'Mirah\'s Song'}},nil,{1422,70.22,73.71},{1422,70.22,73.71},{{5515,"Krastinov's Bag of Horrors"}},nil,{13523,'Blood of Innocents'}},
