  [6041] = {{"Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.","Once you plant the bomb, leave the building and marvel at your handiwork.","By the way, Smokey's Special Compound is rather... unstable."},{{1,'Smokey LaRue'}},{{1,'Smokey LaRue'}},{{5951,'Moist Towelette'},{16992,'Smokey\'s Explosive Launcher'},{16993,'Smokey\'s Fireshooter'},{17523,'Smokey\'s Drape'}},nil,{1423,70.88,48.43},{1423,70.88,48.43},{{6026,"That's Asking A Lot"}},nil,{15736,'Smokey\'s Special Compound'}},
