  [7461] = {{"You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.","Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.","Return to the Shen'dralar Ancient in the courtyard should you complete this quest."},{{1,'Shen\'dralar Ancient'}},{{1,'Shen\'dralar Ancient'}},nil,nil,nil,nil,nil,nil,nil},
