  [7508] = {{"Give the Dull and Flat Elven Blade to Lorekeeper Lydros."},{{3,'A Dull and Flat Elven Blade'}},{{1,'Lorekeeper Lydros'}},nil,nil,nil,nil,{{7507,"Foror's Compendium"}},nil,{18513,'A Dull and Flat Elven Blade'}},
  [7509] = {{"You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.","The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.","Do this and Quel'Serrar will be yours."},{{1,'Lorekeeper Lydros'}},{{1,'Lorekeeper Lydros'}},{{18348,'Quel\'Serrar'}},{{809,200}},nil,nil,{{7508,"The Forging of Quel'Serrar"}},nil,{18489,'Unfired Ancient Blade'}},
