  [7601] = {{"Speak with Impsy in Felwood."},{{1,'Niby the Almighty'}},{{1,'Impsy'}},nil,nil,{1448,41.38,44.85},{1448,41.36,45.02},nil,nil,nil},
  [7602] = {{"Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.","The Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.","Recover the Flawless Fel Essences and return to Impsy in Felwood."},{{1,'Impsy'}},{{1,'Impsy'}},nil,nil,{1448,41.36,45.02},{1448,41.36,45.02},{{7601,"What Niby Commands"}},nil,nil},
  [7603] = {{"Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.","Return Kroshius' Infernal Core to Niby the Almighty in Felwood."},{{1,'Impsy'}},{{1,'Niby the Almighty'}},{{18762,'Shard of the Green Flame'}},nil,{1448,41.36,45.02},{1448,41.38,44.85},{{7602,"Flawless Fel Essence"}},nil,{18626,'Fel Fire'}},
  [7623] = {{"Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.","Use the potions to travel through Jaedenar, and speak with Lord Banehollow."},{{1,'Gorzeeki Wildeyes'}},{{1,'Lord Banehollow'}},nil,nil,{1428,12.44,31.63},{1448,35.93,44.42},nil,nil,nil},
  [7624] = {{"Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar."},{{1,'Lord Banehollow'}},{{1,'Lord Banehollow'}},nil,nil,{1448,35.93,44.42},{1448,35.93,44.42},{{7623,"Lord Banehollow"}},nil,nil},
  [7625] = {{"Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes."},{{1,'Lord Banehollow'}},{{1,'Gorzeeki Wildeyes'}},nil,nil,{1448,35.93,44.42},{1428,12.44,31.63},{{7624,"Ulathek the Traitor"}},nil,nil},
  [7637] = {{"Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it."},{{1,'Lord Grayson Shadowbreaker'}},{{1,'High Priest Rohan'}},nil,{{47,350},{69,150}},{1453,48.43,50.22},{1455,24.73,8.16},{{7638,"Lord Grayson Shadowbreaker"}},nil,nil},
  [7638] = {{"Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."},{{1,'Duthorian Rall'}},{{1,'Lord Grayson Shadowbreaker'}},nil,nil,{1453,50.48,47.49},{1453,48.43,50.22},nil,nil,nil},
  [7639] = {{"Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},{{1,'High Priest Rohan'}},{{1,'Lord Grayson Shadowbreaker'}},nil,{{47,25},{69,25},{72,75}},{1455,24.73,8.16},{1453,48.43,50.22},{{7637,"Emphasis on Sacrifice"}},nil,{18819,'Rohan\'s Exorcism Censer'}},
