  [7641] = {{"Speak with Grimand Elmore in Stormwind's Dwarven District."},{{1,'Lord Grayson Shadowbreaker'}},{{1,'Grimand Elmore'}},nil,nil,{1453,48.43,50.22},{1453,59.73,33.78},{{7640,"Exorcising Terrordale"}},nil,nil},
  [7642] = {{"Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."},{{1,'Grimand Elmore'}},{{1,'Grimand Elmore'}},nil,{{47,250},{69,75},{469,75}},{1453,59.73,33.78},{1453,59.73,33.78},{{7641,"The Work of Grimand Elmore"}},nil,nil},
  [7643] = {{"Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.","Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it."},{{1,'Lord Grayson Shadowbreaker'}},{{1,'Ancient Equine Spirit'}},nil,nil,{1453,48.43,50.22},nil,{{7642,"Collection of Goods"}},nil,{18753,'Arcanite Barding'}},
  [7644] = {{"Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},{{1,'Ancient Equine Spirit'}},{{1,'Lord Grayson Shadowbreaker'}},nil,{{72,350}},nil,{1453,48.43,50.22},{{7643,"Ancient Equine Spirit"}},nil,{18792,'Blessed Arcanite Barding'}},
  [7646] = {{"Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},{{1,'Lord Grayson Shadowbreaker'}},{{1,'Lord Grayson Shadowbreaker'}},nil,{{72,75}},{1453,48.43,50.22},{1453,48.43,50.22},{{7644,"Blessed Arcanite Barding"}},nil,nil},
