  [7666] = {nil,{{1,'Lord Grayson Shadowbreaker'}},{{1,'Lord Grayson Shadowbreaker'}},{{18746,'Divination Scryer'}},nil,{1453,48.43,50.22},{1453,48.43,50.22},{{7647,"Judgment and Redemption"}},nil,nil},
