  [7726] = {{"Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there."},{{1,'Zorbin Fandazzle'}},{{1,'Zorbin Fandazzle'}},nil,{{21,25},{369,25},{470,25},{577,25}},{1444,44.81,43.42},{1444,44.81,43.42},{{7721,"Fuel for the Zapping"}},nil,nil},
