  [7841] = {{"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.","You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands."},{{1,'Otho Moji\'ko'}},{{1,'Otho Moji\'ko'}},nil,nil,{1425,79.38,79.08},{1425,79.38,79.08},nil,nil,nil},
  [7842] = {{"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.","Gryphons are known to inhabit every region of the Hinterlands."},{{1,'Otho Moji\'ko'}},{{1,'Otho Moji\'ko'}},nil,nil,{1425,79.38,79.08},{1425,79.38,79.08},{{7841,"Message to the Wildhammer"}},nil,nil},
  [7843] = {{"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.","Beware of angry Wildhammer dwarves and unruly members of the Alliance."},{{1,'Otho Moji\'ko'}},{{1,'Otho Moji\'ko'}},{{19119,'Owlbeast Hide Gloves'}},nil,{1425,79.38,79.08},{1425,79.38,79.08},{{7842,"Another Message to the Wildhammer"}},nil,{19036,'Final Message to the Wildhammer'}},
  [7845] = {{"Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.","You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands."},{{1,'Primal Torntusk'}},{{1,'Elder Torntusk'}},nil,nil,{1425,78.20,81.18},{1425,59.69,77.84},nil,nil,nil},
