  [8304] = {{"Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.","Once you have gathered the requested information, return to Commander Mar'alith."},{{1,'Commander Mar\'alith'}},{{1,'Commander Mar\'alith'}},nil,{{609,250}},{1451,49.20,34.18},{1451,49.20,34.18},nil,nil,nil},
