  [8306] = {{"Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.","Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.","And $N, remember the Commander's words: \"Do what you must...\""},{{1,'Commander Mar\'alith'}},{{1,'Commander Mar\'alith'}},{{20724,'Corrupted Blackwood Staff'}},{{609,200}},{1451,49.20,34.18},{1451,49.20,34.18},{{8304,"Dearest Natalia"}},nil,nil},
