  [8315] = {{"Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.","You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.","Assemble an army for this task, $N!"},{{1,'Geologist Larksbane'}},{{1,'Geologist Larksbane'}},nil,{{609,200}},{1451,49.67,37.46},{1451,49.67,37.46},{{8314,"Unraveling the Mystery"}},nil,{20464,'Glyphs of Calling'}},
